            iReturn = 3;
        else
            iReturn = 5;
        break;
    case 7:
        iReturn = 3;
        break;
    case 1:
        iReturn = 1;
        break;
    case 3:
        iReturn = 2;
        break;
    case 2:
        iReturn = 2;
        break;
    case 0:
        iReturn = 0;
        break;
    case 10:
        iReturn = 6;
        break;
    default:
